import React, { useState, useEffect } from 'react';
import { getPagos, getJugadores, registrarPago, getTotalDeudaByJugador } from '../../database/db';
import './ControlPagos.css';

function ControlPagos() {
  const [pagos, setPagos] = useState([]);
  const [jugadores, setJugadores] = useState([]);
  const [filtro, setFiltro] = useState('todos');
  const [jugadorSeleccionado, setJugadorSeleccionado] = useState(null);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    cargarDatos();
  }, []);

  const cargarDatos = async () => {
    setLoading(true);
    try {
      const [pagosData, jugadoresData] = await Promise.all([
        getPagos(),
        getJugadores()
      ]);
      setPagos(pagosData);
      setJugadores(jugadoresData);
    } catch (error) {
      console.error('Error cargando datos:', error);
      alert('Error al cargar los datos');
    }
    setLoading(false);
  };

  const handleRegistrarPago = async (pagoId) => {
    if (window.confirm('¿Registrar este pago como pagado?')) {
      try {
        await registrarPago(pagoId);
        await cargarDatos();
        alert('✅ Pago registrado correctamente');
      } catch (error) {
        alert('Error al registrar pago: ' + error.message);
      }
    }
  };

  const pagosFiltrados = () => {
    let filtrados = pagos;
    if (filtro === 'pendientes') {
      filtrados = pagos.filter(p => p.Estado === 'pendiente');
    } else if (filtro === 'pagados') {
      filtrados = pagos.filter(p => p.Estado === 'pagado');
    }
    if (jugadorSeleccionado) {
      filtrados = filtrados.filter(p => p.JugadorId === jugadorSeleccionado);
    }
    return filtrados;
  };

  const getJugadorNombre = (id) => {
    const jugador = jugadores.find(j => j.Id === id);
    return jugador ? `${jugador.Nombre} (#${jugador.NumeroCamiseta})` : 'Desconocido';
  };

  const getConceptoTexto = (concepto) => {
    return concepto === 'entrenamiento' ? '⚽ Entrenamiento' : '🏆 Partido';
  };

  const totalDeuda = pagos.filter(p => p.Estado === 'pendiente').reduce((sum, p) => sum + p.Monto, 0);
  const totalPagado = pagos.filter(p => p.Estado === 'pagado').reduce((sum, p) => sum + p.Monto, 0);

  // Función para obtener deuda de un jugador (async)
  const getDeudaJugador = async (jugadorId) => {
    try {
      return await getTotalDeudaByJugador(jugadorId);
    } catch (error) {
      return 0;
    }
  };

  if (loading && jugadores.length === 0) {
    return <div className="loading-container">Cargando...</div>;
  }

  return (
    <div className="control-pagos">
      <div className="header-actions">
        <h2><i className="fas fa-dollar-sign"></i> Control de Pagos</h2>
      </div>

      <div className="pagos-stats">
        <div className="stat-card-pago">
          <i className="fas fa-clock"></i>
          <div>
            <h3>${totalDeuda.toLocaleString()}</h3>
            <p>Pendiente de cobro</p>
          </div>
        </div>
        <div className="stat-card-pago success">
          <i className="fas fa-check-circle"></i>
          <div>
            <h3>${totalPagado.toLocaleString()}</h3>
            <p>Total recaudado</p>
          </div>
        </div>
      </div>

      <div className="filtros-pagos">
        <div className="filtro-buttons">
          <button className={filtro === 'todos' ? 'active' : ''} onClick={() => setFiltro('todos')}>Todos</button>
          <button className={filtro === 'pendientes' ? 'active' : ''} onClick={() => setFiltro('pendientes')}>Pendientes</button>
          <button className={filtro === 'pagados' ? 'active' : ''} onClick={() => setFiltro('pagados')}>Pagados</button>
        </div>
        <select value={jugadorSeleccionado || ''} onChange={(e) => setJugadorSeleccionado(e.target.value ? parseInt(e.target.value) : null)}>
          <option value="">Todos los jugadores</option>
          {jugadores.map(j => (
            <option key={j.Id} value={j.Id}>{j.Nombre} (#{j.NumeroCamiseta})</option>
          ))}
        </select>
      </div>

      {/* Vista Desktop */}
      <div className="pagos-table-container desktop-view">
        <table className="pagos-table">
          <thead>
            <tr>
              <th>Jugador</th>
              <th>Concepto</th>
              <th>Monto</th>
              <th>Vencimiento</th>
              <th>Estado</th>
              <th>Fecha Pago</th>
              <th>Acciones</th>
            </tr>
          </thead>
          <tbody>
            {pagosFiltrados().map(pago => (
              <tr key={pago.Id} className={pago.Estado === 'pendiente' ? 'pendiente-row' : 'pagado-row'}>
                <td>{getJugadorNombre(pago.JugadorId)}</td>
                <td>{getConceptoTexto(pago.Concepto)}</td>
                <td className="monto">${pago.Monto.toLocaleString()}</td>
                <td>{pago.FechaVencimiento ? new Date(pago.FechaVencimiento).toLocaleDateString() : '-'}</td>
                <td>
                  <span className={`estado-badge ${pago.Estado}`}>
                    {pago.Estado === 'pendiente' ? '⏳ Pendiente' : '✅ Pagado'}
                  </span>
                </td>
                <td>{pago.FechaPago ? new Date(pago.FechaPago).toLocaleDateString() : '-'}</td>
                <td>
                  {pago.Estado === 'pendiente' && (
                    <button className="btn-pagar" onClick={() => handleRegistrarPago(pago.Id)}>
                      <i className="fas fa-check"></i> Pagar
                    </button>
                  )}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* Vista Mobile */}
      <div className="pagos-cards mobile-view">
        {pagosFiltrados().map(pago => (
          <div key={pago.Id} className={`pago-card-mobile ${pago.Estado}`}>
            <div className="pago-header">
              <strong>{getJugadorNombre(pago.JugadorId)}</strong>
              <span className="monto-mobile">${pago.Monto.toLocaleString()}</span>
            </div>
            <div className="pago-body">
              <p><i className="fas fa-tag"></i> {getConceptoTexto(pago.Concepto)}</p>
              <p><i className="fas fa-calendar"></i> Vence: {pago.FechaVencimiento ? new Date(pago.FechaVencimiento).toLocaleDateString() : '-'}</p>
              <p><i className="fas fa-check-circle"></i> Estado: {pago.Estado === 'pendiente' ? 'Pendiente' : 'Pagado'}</p>
              {pago.FechaPago && <p><i className="fas fa-calendar-check"></i> Pagado: {new Date(pago.FechaPago).toLocaleDateString()}</p>}
            </div>
            {pago.Estado === 'pendiente' && (
              <div className="pago-footer">
                <button className="btn-pagar-mobile" onClick={() => handleRegistrarPago(pago.Id)}>
                  <i className="fas fa-check"></i> Registrar Pago
                </button>
              </div>
            )}
          </div>
        ))}
      </div>
    </div>
  );
}

export default ControlPagos;
